DROP FUNCTION IF EXISTS public.admin_dashboard(text,text,integer,uuid);
CREATE OR REPLACE FUNCTION public.admin_dashboard(_section text DEFAULT 'overview'::text, _search text DEFAULT ''::text, _page integer DEFAULT 0, _target uuid DEFAULT NULL::uuid, _demo boolean DEFAULT false)
 RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$ DECLARE uid uuid; d date:=(now() AT TIME ZONE 'Africa/Tunis')::date; rows jsonb:='[]'; result jsonb; v_total int:=0; offset_n int:=greatest(0,_page)*20; demo_d date; BEGIN uid:=public._require_admin(); SELECT max(demo_today) INTO demo_d FROM profiles WHERE is_demo; IF demo_d IS NOT NULL AND _demo THEN d:=demo_d; END IF;
SELECT jsonb_build_object('me',(SELECT jsonb_build_object('id',id,'display_name',display_name,'avatar_url',avatar_url) FROM profiles WHERE id=uid),'sample',(SELECT EXISTS(SELECT 1 FROM seasons WHERE is_demo)),'showing_demo',_demo,'day',d,'open_reports',(SELECT count(DISTINCT post_id) FROM reports),'season',(SELECT to_jsonb(s) FROM seasons s WHERE NOT challenge_owned AND status='live' ORDER BY starts_on LIMIT 1),'demo_counts',jsonb_build_object('profiles',(SELECT count(*) FROM profiles WHERE is_demo),'posts',(SELECT count(*) FROM posts WHERE is_demo),'crews',(SELECT count(*) FROM crews WHERE is_demo),'checkins',(SELECT count(*) FROM checkins WHERE is_demo))) INTO result;
IF _section='overview' THEN RETURN result||jsonb_build_object(
'kpis',jsonb_build_object('active_today',(SELECT count(DISTINCT user_id) FROM checkins WHERE is_demo=_demo AND day=d),'active_previous',(SELECT count(DISTINCT user_id) FROM checkins WHERE is_demo=_demo AND day=d-1),'checkins_today',(SELECT count(*) FROM checkins WHERE is_demo=_demo AND day=d AND value>0),'checkins_previous',(SELECT count(*) FROM checkins WHERE is_demo=_demo AND day=d-1 AND value>0),'average_score',(SELECT coalesce(round(avg(total)),0) FROM daily_scores WHERE is_demo=_demo AND day=d),'average_previous',(SELECT coalesce(round(avg(total)),0) FROM daily_scores WHERE is_demo=_demo AND day=d-1),'retention7',(SELECT coalesce(round(100.0*count(DISTINCT e.user_id) FILTER(WHERE EXISTS(SELECT 1 FROM checkins c WHERE c.user_id=e.user_id AND c.day=(e.joined_at AT TIME ZONE p.timezone)::date+7))/nullif(count(DISTINCT e.user_id),0)),0) FROM season_entries e JOIN profiles p ON p.id=e.user_id WHERE e.is_demo=_demo AND (e.joined_at AT TIME ZONE p.timezone)::date<=d-7),'passes',0,'reports',(SELECT count(DISTINCT post_id) FROM reports WHERE is_demo=_demo)),
'chart',(SELECT jsonb_agg(jsonb_build_object('day',g::date,'value',(SELECT count(*) FROM checkins WHERE is_demo=_demo AND day=g::date AND value>0))) FROM generate_series(d-8,d,interval '1 day')g),
'countries',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM(SELECT p.country_code AS name,count(DISTINCT p.id) AS value FROM profiles p JOIN season_entries e ON e.user_id=p.id WHERE p.show_on_public_board AND p.is_demo=_demo GROUP BY p.country_code ORDER BY count(DISTINCT p.id) DESC LIMIT 6)x),
'activity',(SELECT jsonb_agg(jsonb_build_object('day',g::date,'dau',(SELECT count(DISTINCT user_id) FROM checkins WHERE is_demo=_demo AND day=g::date AND value>0),'wau',(SELECT count(DISTINCT user_id) FROM checkins WHERE is_demo=_demo AND day BETWEEN g::date-6 AND g::date AND value>0))) FROM generate_series(d-8,d,interval '1 day')g),
'signups',(SELECT jsonb_agg(jsonb_build_object('day',g::date,'value',(SELECT count(*) FROM profiles WHERE is_demo=_demo AND (created_at AT TIME ZONE timezone)::date=g::date))) FROM generate_series(d-8,d,interval '1 day')g),
'histogram',(SELECT jsonb_agg(jsonb_build_object('label',g*50||'–'||(g*50+49),'value',(SELECT count(*) FROM daily_scores WHERE is_demo=_demo AND day=d AND total BETWEEN g*50 AND g*50+49))) FROM generate_series(0,7)g),
'retention',(SELECT jsonb_agg(jsonb_build_object('day',n,'eligible',(SELECT count(*) FROM profiles WHERE is_demo=_demo AND (created_at AT TIME ZONE timezone)::date<=d-n),'value',(SELECT coalesce(round(100.0*count(*) FILTER(WHERE EXISTS(SELECT 1 FROM checkins c WHERE c.user_id=p.id AND c.day=(p.created_at AT TIME ZONE p.timezone)::date+n))/nullif(count(*),0)),0) FROM profiles p WHERE p.is_demo=_demo AND (p.created_at AT TIME ZONE p.timezone)::date<=d-n))) FROM unnest(ARRAY[1,7,30])n));
ELSIF _section='seasons' THEN SELECT coalesce(jsonb_agg(to_jsonb(s)||jsonb_build_object('players',(SELECT count(*) FROM season_entries e WHERE e.season_id=s.id)) ORDER BY s.starts_on),'[]') INTO rows FROM seasons s WHERE NOT s.archived AND (NOT s.challenge_owned OR s.is_demo); result:=result||jsonb_build_object('bosses',(SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY b.week_no),'[]') FROM bosses b WHERE NOT archived AND season_id=coalesce(_target,(SELECT id FROM seasons WHERE status='live' AND NOT challenge_owned ORDER BY starts_on LIMIT 1))));
ELSIF _section='users' THEN SELECT count(*) INTO v_total FROM profiles WHERE display_name ILIKE '%'||_search||'%' OR handle ILIKE '%'||_search||'%'; SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO rows FROM(SELECT p.id,p.handle,p.display_name,p.avatar_url,p.country_code,p.account_status,p.is_demo,CASE WHEN p.is_admin THEN 'admin' WHEN EXISTS(SELECT 1 FROM user_roles WHERE user_id=p.id AND role='creator') THEN 'creator' ELSE 'user' END role,(SELECT string_agg(c.name,', ') FROM crews c JOIN crew_members m ON m.crew_id=c.id WHERE m.user_id=p.id AND NOT c.archived) crew,coalesce((SELECT streak FROM daily_scores WHERE user_id=p.id ORDER BY day DESC LIMIT 1),0) streak,coalesce((SELECT sum(total) FROM daily_scores WHERE user_id=p.id),0)+coalesce((SELECT sum(points) FROM bonus_points WHERE user_id=p.id),0) points FROM profiles p WHERE display_name ILIKE '%'||_search||'%' OR handle ILIKE '%'||_search||'%' ORDER BY p.created_at DESC LIMIT 20 OFFSET offset_n)x;
ELSIF _section='moderation' THEN SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO rows FROM(SELECT p.*,pr.handle,pr.display_name,(SELECT count(*) FROM reports r WHERE r.post_id=p.id) reports,(SELECT string_agg(DISTINCT reason,' · ') FROM reports r WHERE r.post_id=p.id) reasons FROM posts p JOIN profiles pr ON pr.id=p.user_id WHERE EXISTS(SELECT 1 FROM reports WHERE post_id=p.id) OR EXISTS(SELECT 1 FROM admin_suspicious_activity WHERE status<>'resolved' AND detail->>'post_id'=p.id::text) ORDER BY p.created_at DESC LIMIT 60)x; result:=result||jsonb_build_object('filters',(SELECT coalesce(jsonb_agg(to_jsonb(w)),'[]') FROM admin_word_filters w),'flags',(SELECT coalesce(jsonb_object_agg(key,enabled),'{}') FROM admin_feature_flags));
ELSIF _section='creators' THEN SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO rows FROM(SELECT p.id AS user_id,p.handle,p.display_name,r.id,r.code,r.featured,r.signups,0 passes FROM user_roles u JOIN profiles p ON p.id=u.user_id LEFT JOIN creator_referrals r ON r.user_id=p.id WHERE u.role='creator')x; result:=result||jsonb_build_object('sponsored',(SELECT count(*) FROM bosses WHERE sponsor IS NOT NULL AND NOT archived),'boss_count',(SELECT count(*) FROM bosses WHERE NOT archived),'challenges',(SELECT coalesce(jsonb_agg(to_jsonb(ch)),'[]') FROM challenges ch WHERE audience='creator' AND NOT archived));
ELSIF _section='crews' THEN SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO rows FROM(SELECT c.*,p.handle AS owner,(SELECT count(*) FROM crew_members WHERE crew_id=c.id) members,(SELECT audience FROM challenges WHERE crew_id=c.id LIMIT 1) audience FROM crews c JOIN profiles p ON p.id=c.owner_id WHERE NOT c.archived ORDER BY c.created_at DESC)x; result:=result||jsonb_build_object('challenges',(SELECT coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('owner',(SELECT handle FROM profiles WHERE id=c.owner_id),'members',(SELECT count(*) FROM season_entries WHERE season_id=c.season_id))),'[]') FROM challenges c WHERE NOT archived),'members',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'handle',p.handle,'display_name',p.display_name,'role',m.role)),'[]') FROM crew_members m JOIN profiles p ON p.id=m.user_id WHERE crew_id=_target));
ELSIF _section='habits' THEN SELECT coalesce(jsonb_agg(to_jsonb(h) ORDER BY sort),'[]') INTO rows FROM habit_templates h WHERE NOT archived;
ELSIF _section='anticheat' THEN SELECT coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('handle',p.handle) ORDER BY a.created_at DESC),'[]') INTO rows FROM admin_suspicious_activity a JOIN profiles p ON p.id=a.user_id WHERE status<>'resolved';
ELSIF _section='broadcast' THEN SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY scheduled_at DESC),'[]') INTO rows FROM announcements a;
ELSIF _section='flags' THEN SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY key),'[]') INTO rows FROM admin_feature_flags f;
ELSIF _section='audit' THEN SELECT count(*) INTO v_total FROM admin_audit_log; SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO rows FROM(SELECT a.*,p.display_name AS admin_name FROM admin_audit_log a LEFT JOIN profiles p ON p.id=a.admin_id ORDER BY a.created_at DESC LIMIT 20 OFFSET offset_n)x;
ELSIF _section<>'demo' THEN RAISE EXCEPTION 'invalid_section'; END IF;
RETURN result||jsonb_build_object('rows',rows,'total',v_total,'page',_page); END $function$;
REVOKE ALL ON FUNCTION public.admin_dashboard(text,text,integer,uuid,boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_dashboard(text,text,integer,uuid,boolean) TO authenticated;